import zipfile, re, xml.etree.ElementTree as ET

ns = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
with zipfile.ZipFile('budget.xlsx') as z:
    print('FILES:', z.namelist())
    for name in z.namelist():
        if name.startswith('xl/worksheets/sheet') or name == 'xl/sharedStrings.xml':
            print('=====', name)
            data = z.read(name)
            if name == 'xl/sharedStrings.xml':
                root = ET.fromstring(data)
                for i, si in enumerate(root.findall('m:si', ns)):
                    text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
                    print(i, repr(text))
            else:
                print(data.decode('utf-8', errors='replace'))
